import itertools

def solve():
    ages = [20, 22, 24, 26, 28, 30]
    # S1=52, S2=50, S3=48 based on 150 total and difference of 2
    for p in itertools.permutations(ages):
        P, Q, R, S, T, U = p
        if P != 22: continue
        if T != S + 6: continue

        # Try all possible ways to partition the 6 people into 3 pairs
        # Q must be in Pair 1 (Sum 52)
        # R must be 4 older than his partner
        names = ['P', 'Q', 'R', 'S', 'T', 'U']
        val = {'P':P, 'Q':Q, 'R':R, 'S':S, 'T':T, 'U':U}

        # Q is in Pair 1, so find Q's partner
        for partner_q in [n for n in names if n != 'Q']:
            if val['Q'] + val[partner_q] == 52:
                if val['Q'] > val[partner_q]:
                    # Check R's pair
                    for partner_r in [n for n in names if n not in ['Q', partner_q, 'R']]:
                        if val['R'] == val[partner_r] + 4:
                            sum_r = val['R'] + val[partner_r]
                            # The last pair must be the remaining two people
                            others = [n for n in names if n not in ['Q', partner_q, 'R', partner_r]]
                            sum_other = val[others[0]] + val[others[1]]

                            # Sums must be 52, 50, 48 in some order corresponding to Pair 1, 2, 3
                            # Q is in Pair 1 (52), R's pair must be 50 or 48
                            if sum_r in [50, 48] and sum_other in [50, 48] and sum_r != sum_other:
                                if sum_r == 48 and sum_other == 50:
                                    return val[partner_q]
    return None

answer = solve()

import itertools
players = ['A', 'B', 'C', 'D', 'E']
matches = list(itertools.combinations(players, 2))
valid_results = []
